INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_LOST_CIV','Department of Lost Things'),
 ('TXT_KEY_CWC3_LOST_SHORT','Department of Lost Things'),
 ('TXT_KEY_CWC3_LOST_ADJECTIVE','Departmental'),
 ('TXT_KEY_CWC3_LOST_LEADER','Chief Registrar Nobody'),
 ('TXT_KEY_CWC3_LOST_TRAIT','Nothing Is Ever Truly Lost'),
 ('TXT_KEY_CWC3_LOST_TRAIT_HELP','Enemy combat units killed by Department combat units within 3 tiles of an owned city recover one Curio for the nearest city (ties: lowest city ID). Maximum 4 per city; each supplies +1 Culture and +1 Science every turn. Ordinary Barbarian combat qualifies. Captures pause that Department''s ledger until recapture; destroyed cities lose their Curios.'),
 ('TXT_KEY_CWC3_LOST_CIV_PEDIA','A supernatural lost-property administration catalogs the things the world forgets. Chief Registrar Nobody turns battlefield recoveries into an enduring civic collection.'),
 ('TXT_KEY_CWC3_LOST_STRATEGY','Defend compact city clusters, recover Curios from genuine combat, and build Offices in mature collections. Convert recurring Science into technology and Culture into policies and later Tourism.'),
 ('TXT_KEY_CWC3_LOST_LEADER_PEDIA','A supernatural lost-property administration catalogs the things the world forgets. Chief Registrar Nobody turns battlefield recoveries into an enduring civic collection.'),
 ('TXT_KEY_CWC3_LOST_DAWN','Chief Registrar Nobody, guide Department of Lost Things. Defend compact city clusters, recover Curios from genuine combat, and build Offices in mature collections. Convert recurring Science into technology and Culture into policies and later Tourism.'),
 ('TXT_KEY_CWC3_LOST_UNIT','Retrieval Officer'),
 ('TXT_KEY_CWC3_LOST_UNIT_HELP','Replaces the active CP Spearman. +1 Sight and +15% Combat Strength against Barbarians. Unique promotion persists through upgrades.'),
 ('TXT_KEY_CWC3_LOST_UNIT_PEDIA','A supernatural lost-property administration catalogs the things the world forgets. Chief Registrar Nobody turns battlefield recoveries into an enduring civic collection. +1 Sight and +15% Combat Strength against Barbarians. Unique promotion persists through upgrades.'),
 ('TXT_KEY_CWC3_LOST_UNIT_STRATEGY','+1 Sight and +15% Combat Strength against Barbarians. Unique promotion persists through upgrades. Preserves all other active CP unit properties and companions.'),
 ('TXT_KEY_CWC3_LOST_BUILDING','Lost Property Office'),
 ('TXT_KEY_CWC3_LOST_BUILDING_HELP','Replaces the active CP Library. +1 Culture and +1 Gold per Recovered Curio, in addition to all active Library effects. At four Curios: UA +4 Culture/+4 Science, Office +4 Culture/+4 Gold.'),
 ('TXT_KEY_CWC3_LOST_BUILDING_PEDIA','A supernatural lost-property administration catalogs the things the world forgets. Chief Registrar Nobody turns battlefield recoveries into an enduring civic collection. +1 Culture and +1 Gold per Recovered Curio, in addition to all active Library effects. At four Curios: UA +4 Culture/+4 Science, Office +4 Culture/+4 Gold.'),
